package com.tripmateai.service;
import com.tripmateai.ai.AiProviderClient; import com.tripmateai.dto.request.ai.AiTripPlanRequest; import com.tripmateai.dto.response.ai.*; import com.tripmateai.entity.*; import com.tripmateai.enums.TravelPreference; import com.tripmateai.repository.*; import com.tripmateai.security.UserPrincipal; import com.tripmateai.service.impl.AiTripPlannerServiceImpl; import org.junit.jupiter.api.*; import org.mockito.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import java.math.BigDecimal; import java.time.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class AiTripPlannerServiceImplTest { @Mock AiProviderClient provider; @Mock DestinationRepository destinations; @Mock TripRepository trips; @Mock ItineraryRepository itineraries; @Mock ActivityRepository activities; @InjectMocks AiTripPlannerServiceImpl service; @BeforeEach void setup(){MockitoAnnotations.openMocks(this);var user=new User();user.setId(1L);SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(new UserPrincipal(user),null,List.of()));} @AfterEach void clear(){SecurityContextHolder.clearContext();} @Test void savesStructuredPlanAsOwnedTrip(){var dest=new Destination();dest.setId(2L);dest.setCity("Goa");dest.setCountry("India");var request=new AiTripPlanRequest("AI Goa",2L,LocalDate.now().plusDays(2),1,new BigDecimal("300"),2,Set.of(TravelPreference.BEACH));var days=List.of(new AiItineraryDayResponse(1,"Arrival",List.of(new AiActivityPlanResponse("Beach","Relax","Goa Beach",LocalTime.of(10,0),LocalTime.of(12,0),new BigDecimal("25")))));when(destinations.findById(2L)).thenReturn(Optional.of(dest));when(provider.generate(request,dest)).thenReturn(days);when(trips.save(any())).thenAnswer(x->{var t=x.getArgument(0,Trip.class);t.setId(10L);return t;});when(itineraries.save(any())).thenAnswer(x->{var i=x.getArgument(0,Itinerary.class);i.setId(11L);return i;});var result=service.generate(request);assertEquals(10L,result.trip().id());verify(activities).save(argThat(a->a.getItinerary().getId().equals(11L)&&a.getSortOrder()==1));}}
